    private val R_HIP = floatArrayOf(36.00f, 33.03f, 29.63f, 25.92f, 22.00f, 17.97f, 13.91f, 9.90f, 6.00f, 2.28f, -1.28f, -4.70f, -8.00f, -11.20f, -14.28f, -17.22f, -20.00f, -22.57f, -24.84f, -26.69f, -28.00f, -28.67f, -28.62f, -27.75f, -26.00f, -23.37f, -20.20f, -16.93f, -14.00f, -11.71f, -9.85f, -8.06f, -6.00f, -3.38f, -0.17f, 3.63f, 8.00f, 12.90f, 18.26f, 23.99f, 30.00f, 36.20f, 42.49f, 48.79f, 55.00f, 60.94f, 66.14f, 70.01f, 72.00f, 71.73f, 69.58f, 66.15f, 62.00f, 57.66f, 53.40f, 49.44f, 46.00f, 43.19f, 40.80f, 38.51f)
    private val R_KNEE = floatArrayOf(14.00f, 17.28f, 22.50f, 28.48f, 34.00f, 38.09f, 40.68f, 41.93f, 42.00f, 41.05f, 39.28f, 36.86f, 34.00f, 30.91f, 27.96f, 25.52f, 24.00f, 23.73f, 24.90f, 27.61f, 32.00f, 38.09f, 45.46f, 53.60f, 62.00f, 70.20f, 78.01f, 85.32f, 92.00f, 97.96f, 103.24f, 107.90f, 112.00f, 115.57f, 118.51f, 120.70f, 122.00f, 122.32f, 121.71f, 120.24f, 118.00f, 115.09f, 111.77f, 108.32f, 105.00f, 101.94f, 98.57f, 94.17f, 88.00f, 79.63f, 69.82f, 59.59f, 50.00f, 41.85f, 35.03f, 29.20f, 24.00f, 19.27f, 15.55f, 13.56f)
    private val R_ARM = floatArrayOf(-30.38f, -27.30f, -23.78f, -19.84f, -15.50f, -10.78f, -5.73f, -0.38f, 5.21f, 11.00f, 16.92f, 22.90f, 28.88f, 34.77f, 40.50f, 45.99f, 51.16f, 55.93f, 60.23f, 64.00f, 67.17f, 69.69f, 71.52f, 72.63f, 73.00f, 72.63f, 71.52f, 69.69f, 67.17f, 64.00f, 60.23f, 55.93f, 51.16f, 45.99f, 40.50f, 34.77f, 28.88f, 22.90f, 16.92f, 11.00f, 5.21f, -0.38f, -5.73f, -10.78f, -15.50f, -19.84f, -23.78f, -27.30f, -30.38f, -33.00f, -35.15f, -36.83f, -38.04f, -38.76f, -39.00f, -38.76f, -38.04f, -36.83f, -35.15f, -33.00f)
    private val R_ELB = floatArrayOf(81.06f, 82.11f, 83.29f, 84.60f, 86.00f, 87.49f, 89.06f, 90.67f, 92.33f, 94.00f, 95.67f, 97.33f, 98.94f, 100.51f, 102.00f, 103.40f, 104.71f, 105.89f, 106.94f, 107.86f, 108.62f, 109.22f, 109.65f, 109.91f, 110.00f, 109.91f, 109.65f, 109.22f, 108.62f, 107.86f, 106.94f, 105.89f, 104.71f, 103.40f, 102.00f, 100.51f, 98.94f, 97.33f, 95.67f, 94.00f, 92.33f, 90.67f, 89.06f, 87.49f, 86.00f, 84.60f, 83.29f, 82.11f, 81.06f, 80.14f, 79.38f, 78.78f, 78.35f, 78.09f, 78.00f, 78.09f, 78.35f, 78.78f, 79.38f, 80.14f)
    private val R_ABD = floatArrayOf(23.33f, 22.40f, 21.37f, 20.23f, 19.00f, 17.69f, 16.33f, 14.91f, 13.46f, 12.00f, 10.54f, 9.09f, 7.67f, 6.31f, 5.00f, 3.77f, 2.63f, 1.60f, 0.67f, -0.12f, -0.79f, -1.31f, -1.69f, -1.92f, -2.00f, -1.92f, -1.69f, -1.31f, -0.79f, -0.12f, 0.67f, 1.60f, 2.63f, 3.77f, 5.00f, 6.31f, 7.67f, 9.09f, 10.54f, 12.00f, 13.46f, 14.91f, 16.33f, 17.69f, 19.00f, 20.23f, 21.37f, 22.40f, 23.33f, 24.12f, 24.79f, 25.31f, 25.69f, 25.92f, 26.00f, 25.92f, 25.69f, 25.31f, 24.79f, 24.12f)
    private val R_STR = floatArrayOf(0.96f, 0.91f, 0.82f, 0.73f, 0.64f, 0.55f, 0.46f, 0.37f, 0.28f, 0.19f, 0.10f, 0.01f, -0.08f, -0.17f, -0.26f, -0.35f, -0.44f, -0.53f, -0.62f, -0.71f, -0.80f, -0.89f, -0.96f, -0.94f, -0.87f, -0.80f, -0.72f, -0.65f, -0.58f, -0.51f, -0.43f, -0.36f, -0.29f, -0.22f, -0.14f, -0.07f, -0.02f, -0.00f, -0.00f, 0.00f, 0.00f, 0.00f, 0.00f, 0.00f, 0.00f, 0.00f, 0.00f, 0.00f, 0.02f, 0.08f, 0.17f, 0.25f, 0.33f, 0.42f, 0.50f, 0.58f, 0.67f, 0.75f, 0.83f, 0.91f)

    /** cyclic linear lookup, u in cycles (any value) */
    private fun cyc(a: FloatArray, u: Float): Float {
        if (u.isNaN()) return a[0]
        val n = a.size
        val x = (u - floor(u)) * n
        var i = x.toInt(); if (i >= n) i = n - 1
        val f = x - i
        val j = if (i + 1 >= n) 0 else i + 1
        return a[i] + (a[j] - a[i]) * f
    }

    private fun ch(w: FloatArray, r: FloatArray, u: Float, rw: Float, kw: Float, kr: Float): Float {
        val a = cyc(w, u) * kw; val b = cyc(r, u) * kr
        return (a + (b - a) * rw) * D2R
    }

    /** stride extension (deg) of the hip at phase [u]: see gen_locomotion.py (_stride_shape). Walk: 0 at 1 m/s .. 22 deg at 3.5 m/s; run: 0 at 3 m/s .. 28 deg at 7.4 m/s. */
    private fun stride(u: Float, rw: Float, speed: Float): Float {
        val kw = 22f * ((speed - 1f) / 2.5f).coerceIn(0f, 1f)
        val kr = 28f * ((speed - 3f) / 4.4f).coerceIn(0f, 1f)
        return (cyc(W_STR, u) * kw * (1f - rw) + cyc(R_STR, u) * kr * rw) * D2R
    }

    /**
     * Fills [o] for the walk phase [walk] (rad, the value that Gait.omega() integrates), blend [run] 0..1 (0 = walk clip, 1 = run clip) and the ground speed [speed] (m/s).
     * The stride grows with the speed: hip swing walk up to +10 % / run up to +12 %, plus the stride extension of stride() (v50 anti foot-skating: walk up to 22 deg, run up to 28 deg at the stance / reach phases). The caller multiplies everything by its own "moving" weight, so a standing character stays in its idle pose.
     */
    fun sample(walk: Float, run: Float, speed: Float, o: Out) {
        val u = walk / TWO_PI; val ub = u + 0.5f
        val rw = if (run < 0f) 0f else if (run > 1f) 1f else run
        val kw = 1f + 0.10f * ((speed - 1.5f) / 4.5f).coerceIn(0f, 1f)
        val kr = 1f + 0.12f * ((speed - 6f) / 4f).coerceIn(0f, 1f)
        o.hipL = ch(W_HIP, R_HIP, u, rw, kw, kr) + stride(u, rw, speed); o.hipR = ch(W_HIP, R_HIP, ub, rw, kw, kr) + stride(ub, rw, speed)
        o.kneeL = -ch(W_KNEE, R_KNEE, u, rw, 1f, 1f); o.kneeR = -ch(W_KNEE, R_KNEE, ub, rw, 1f, 1f)
        o.armL = ch(W_ARM, R_ARM, u, rw, kw, kr); o.armR = ch(W_ARM, R_ARM, ub, rw, kw, kr)
        o.foreL = ch(W_ELB, R_ELB, u, rw, 1f, 1f); o.foreR = ch(W_ELB, R_ELB, ub, rw, 1f, 1f)
        o.abdL = cyc(R_ABD, u) * rw * D2R; o.abdR = cyc(R_ABD, ub) * rw * D2R
        o.lean = -(0.045f + (0.12f - 0.045f) * rw)
        // walk: left shoulder back at the left heel strike (u = 0); run: left shoulder back when the left leg drives forward (u = 0.9)
        o.twist = 0.07f * (1f - rw) * cos(u * TWO_PI) + 0.17f * rw * cos((u - 0.9f) * TWO_PI)
        o.roll = (0.02f + 0.015f * rw) * sin(u * TWO_PI)
    }
}
